export const aboniran = mysqlTable(
  'aboniran',
  {
    aboniranId: int('aboniran_id').autoincrement().notNull(),
    abozakvo: int().default(0).notNull(),
    aboemail: varchar({ length: 255 }),
    abostatiaid: int().default(0).notNull(),
    abostatiaime: varchar({ length: 511 }),
    abostatialin: varchar({ length: 511 }),
    aboavtorid: int().default(0).notNull(),
    data: varchar({ length: 31 }),
    otkaz: int().default(1).notNull(),
  },
  table => [primaryKey({ columns: [table.aboniranId], name: 'aboniran_aboniran_id' })],
);

export const abzac = mysqlTable(
  'abzac',
  {
    abzacId: int('abzac_id').autoincrement().notNull(),
    statId: int('stat_id'),
    nred: int(),
    rt: int(),
    tt1: int(),
    tr1: int(),
    tc1: varchar({ length: 50 }),
    fc1: varchar({ length: 50 }),
    ht1: int(),
    hp1: int(),
    vt1: int(),
    vp1: int(),
    txt1: text(),
    pic1: varchar({ length: 255 }),
    tt2: int(),
    tr2: int(),
    tc2: varchar({ length: 50 }),
    fc2: varchar({ length: 50 }),
    ht2: int(),
    hp2: int(),
    vt2: int(),
    vp2: int(),
    txt2: text(),
    pic2: varchar({ length: 255 }),
    picL1: varchar('pic_l1', { length: 255 }),
    picL2: varchar('pic_l2', { length: 255 }),
    flX1: int('fl_x1'),
    flY1: int('fl_y1'),
    flX2: int('fl_x2'),
    flY2: int('fl_y2'),
    pti1: int(),
    pti2: int(),
    text1FonPic: varchar('text_1_fon_pic', { length: 255 }),
    pic1Fon: varchar('pic_1_fon', { length: 50 }),
    vrGal1: int('vr_gal_1'),
    pic1Alt: varchar('pic_1_alt', { length: 255 }),
    pic1Title: varchar('pic_1_title', { length: 255 }),
    text2FonPic: varchar('text_2_fon_pic', { length: 255 }),
    pic2Fon: varchar('pic_2_fon', { length: 50 }),
    vrGal2: int('vr_gal_2'),
    pic2Alt: varchar('pic_2_alt', { length: 255 }),
    pic2Title: varchar('pic_2_title', { length: 255 }),
    javrazAli: int('javraz_ali'),
    javrazAlit: int('javraz_alit'),
  },
  table => [primaryKey({ columns: [table.abzacId], name: 'abzac_abzac_id' })],
);

export const avatar = mysqlTable(
  'avatar',
  {
    aid: int().autoincrement().notNull(),
    ime: varchar({ length: 127 }),
    vid: int().default(2).notNull(),
    nom: int().default(0).notNull(),
  },
  table => [primaryKey({ columns: [table.aid], name: 'avatar_aid' })],
);

export const avtori = mysqlTable(
  'avtori',
  {
    avtoriId: int('avtori_id').autoincrement().notNull(),
    vhod: varchar({ length: 127 }),
    parola: varchar({ length: 127 }),
    ime: varchar({ length: 255 }),
    imeLin: varchar('ime_lin', { length: 255 }),
    nik: varchar({ length: 127 }),
    profi: varchar({ length: 255 }),
    opisanie: text(),
    pic: varchar({ length: 255 }),
    dateposl: timestamp({ mode: 'string' }).defaultNow().onUpdateNow(),
    sait: varchar({ length: 255 }),
    email: varchar({ length: 255 }),
    brstr: int().default(0).notNull(),
    brcoment: int().default(0).notNull(),
    belejki: text(),
    alt: varchar({ length: 255 }),
    title: varchar({ length: 255 }),
    tagTitle: varchar('tag_title', { length: 255 }),
    tagDescription: varchar('tag_description', { length: 511 }),
    tagKeywords: varchar('tag_keywords', { length: 511 }),
    info: varchar({ length: 511 }),
    blok: int().default(2).notNull(),
  },
  table => [primaryKey({ columns: [table.avtoriId], name: 'avtori_avtori_id' })],
);

