export const bank = mysqlTable(
  'bank',
  {
    bid: int().autoincrement().notNull(),
    kid: int().notNull(),
    bim: varchar({ length: 255 }),
    ibn: varchar({ length: 63 }),
    bic: varchar({ length: 63 }),
    ezu: varchar({ length: 7 }),
    num: int().default(0).notNull(),
    bip: varchar({ length: 255 }),
  },
  table => [
    index('ezu').on(table.ezu),
    index('num').on(table.num),
    primaryKey({ columns: [table.bid], name: 'bank_bid' }),
  ],
);

