export const zapfak = mysqlTable(
  'zapfak',
  {
    id: int().autoincrement().notNull(),
    dat: varchar({ length: 31 }),
    koi: int().default(0).notNull(),
    por: int().default(0).notNull(),
    sad: mediumtext(),
    tdds: int().default(1).notNull(),
    ez: varchar({ length: 7 }),
    firm: int().default(0).notNull(),
    firmIzdalIme: varchar('firm_izdal_ime', { length: 255 }),
    izdal: varchar({ length: 255 }),
    bank: int().default(0).notNull(),
    faknom: varchar({ length: 31 }),
    fakdat: varchar({ length: 31 }),
    fakDateDanSabitie: varchar('fak_date_dan_sabitie', { length: 31 }),
    pordat: varchar({ length: 31 }),
    obshto: float().notNull(),
    ddsStavka: int('dds_stavka').default(0).notNull(),
    dds: float().notNull(),
    suma: float().notNull(),
    kurs: float().notNull(),
    sumalv: float().notNull(),
    darjava: varchar({ length: 127 }),
    firma: varchar({ length: 255 }),
    poluchil: varchar({ length: 255 }),
    eik: varchar({ length: 63 }),
    tva: varchar({ length: 63 }),
    tipPlashtane: varchar('tip_plashtane', { length: 31 }),
    posledenZapis: int('posleden_zapis').default(1).notNull(),
    koment: text(),
  },
  table => [index('por').on(table.por), primaryKey({ columns: [table.id], name: 'zapfak_id' })],
);

